// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title ScoreSubmit
 * @notice Pay a configurable fee in USDC to submit scores on Base Mainnet.
 * @dev USDC-only accounting. The submission fee is owner-adjustable post-deployment (e.g. for
 *      promotional discounts) so it never requires a redeploy / re-whitelisting on integrators.
 */
